import * as React from "react"

function HeroSectionWithBackgroundGradient({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="hero-section-with-background-gradient"
      className={className}
      {...props}
    >
      <section className="bg-gradient-to-br from-purple-500 to-pink-500 py-16 md:py-32">
          <div className="container mx-auto px-4 md:px-8 text-center">
              <h1 className="text-white font-bold text-4xl md:text-6xl leading-tight mb-6">Welcome to our <br />Colorful World</h1>
              <p className="text-white text-lg md:text-2xl mb-12">Experience the magic of colors with our unique products and
                  services.</p>
              <a href="#"
                  className="bg-white text-purple-500 font-bold py-2 px-8 rounded-full hover:bg-purple-500 hover:text-white transition duration-200">Shop
                  Now</a>
          </div>
      </section>
    </div>
  )
}

export { HeroSectionWithBackgroundGradient }
